// lineorigin は、レビューの指摘の対象の行が、全量の起点 (ブランチの作り始めのコミット) から、
// レビューした内容まで変わっていないかを確かめる。review-triage の判定ノード D8 の条件 (1)。
//
// 結果は「成り立つ」(holds)・「成り立たない」(not-holds)・「確かめられない」(unverifiable) の 3 つで、
// 理由と行ごとの内訳を添えて標準出力に書く。入力の誤り (フラグの不足・解決できない版・
// レビューした内容に無いファイルや行) は結果にせず、標準エラー出力に書いて終了コード 2 で終わる。
//
// 使い方 (-root はリポジトリのルートか、その中のディレクトリの絶対パス):
//
//	go run -C <展開先>/tools/lineorigin . -root "$(pwd)" -base <全量の起点> -file <ファイル> -lines <行> -rev <コミット>
//	go run -C <展開先>/tools/lineorigin . -root "$(pwd)" -base <全量の起点> -file <ファイル> -lines <開始>-<終了> -worktree
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// run はフラグを読んで確かめ、結果を stdout に書く。戻り値は終了コード (0: 結果を出した、2: 入力の誤り)。
func run(args []string, stdout, stderr io.Writer) int {
	opts, err := parseFlags(args, stderr)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	res, err := check(opts)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	writeResult(stdout, res)
	return 0
}

type options struct {
	root     string // -root (絶対パス)
	base     string // -base
	file     string // -file (ルートからの相対パス。整えたもの)
	from, to int    // -lines
	rev      string // -rev (-worktree のときは空)
	worktree bool   // -worktree
}

func parseFlags(args []string, stderr io.Writer) (options, error) {
	fs := flag.NewFlagSet("lineorigin", flag.ContinueOnError)
	fs.SetOutput(stderr)
	root := fs.String("root", "", "リポジトリのルートか、その中のディレクトリの絶対パス (必須)")
	base := fs.String("base", "", "全量の起点 (必須)。コミットに解決できる版")
	file := fs.String("file", "", "指摘の file (必須)。リポジトリのルートからの相対パス")
	lines := fs.String("lines", "", "指摘の行 (必須)。「12」か「12-15」の形")
	rev := fs.String("rev", "", "レビューした内容のコミット。結果のファイルで受け取ったレビューならその head。-worktree と同時には使えない")
	worktree := fs.Bool("worktree", false, "レビューした内容が作業ツリー (コミットしていない変更を含む) のとき。-rev と同時には使えない")
	if err := fs.Parse(args); err != nil {
		return options{}, err
	}
	if fs.NArg() > 0 {
		return options{}, fmt.Errorf("余分な引数があります: %s", strings.Join(fs.Args(), " "))
	}
	var missing []string
	for _, f := range []struct {
		name, value string
	}{{"-root", *root}, {"-base", *base}, {"-file", *file}, {"-lines", *lines}} {
		if f.value == "" {
			missing = append(missing, f.name)
		}
	}
	if len(missing) > 0 {
		return options{}, fmt.Errorf("必須のフラグがありません: %s", strings.Join(missing, " "))
	}
	if (*rev == "") == !*worktree {
		return options{}, errors.New("レビューした内容を、-rev <コミット> か -worktree のどちらか 1 つで指定してください")
	}
	if !filepath.IsAbs(*root) {
		return options{}, fmt.Errorf("-root には絶対パスを渡してください (go run -C で実行すると、相対パスは道具のディレクトリを基準に読まれます): %s", *root)
	}
	f, err := normalizeFile(*file)
	if err != nil {
		return options{}, err
	}
	from, to, err := parseLines(*lines)
	if err != nil {
		return options{}, err
	}
	return options{root: *root, base: *base, file: f, from: from, to: to, rev: *rev, worktree: *worktree}, nil
}

// normalizeFile は -file をルートからの相対パスに整える。ルートの外を指すパスは受け付けない。
func normalizeFile(file string) (string, error) {
	if filepath.IsAbs(file) {
		return "", fmt.Errorf("-file にはリポジトリのルートからの相対パスを渡してください: %s", file)
	}
	clean := filepath.ToSlash(filepath.Clean(file))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, "../") {
		return "", fmt.Errorf("-file がリポジトリの中のファイルを指していません: %s", file)
	}
	return clean, nil
}

// parseLines は「12」か「12-15」を読む。
func parseLines(s string) (int, int, error) {
	a, b, isRange := strings.Cut(s, "-")
	from, err := strconv.Atoi(a)
	if err != nil || from < 1 {
		return 0, 0, fmt.Errorf("-lines は「12」か「12-15」の形で、1 以上の行番号を渡してください: %s", s)
	}
	if !isRange {
		return from, from, nil
	}
	to, err := strconv.Atoi(b)
	if err != nil || to < from {
		return 0, 0, fmt.Errorf("-lines は「12」か「12-15」の形で、終わりを始め以上にしてください: %s", s)
	}
	return from, to, nil
}

func writeResult(w io.Writer, res result) {
	fmt.Fprintf(w, "result: %s\n", res.kind)
	fmt.Fprintf(w, "reason: %s\n", res.reason)
	for _, l := range res.lines {
		fmt.Fprintf(w, "line %d: %s\n", l.line, l.note)
	}
}

package main

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// 結果の 3 つの値。D8 の条件 (1) が成り立つ・成り立たない・確かめられない。
const (
	holds        = "holds"
	notHolds     = "not-holds"
	unverifiable = "unverifiable"
)

type result struct {
	kind   string
	reason string
	lines  []lineResult // 行ごとの内訳。行を調べる前に結果が決まったときは空
}

type lineResult struct {
	line int
	kind string
	note string
}

// check は、opts の行が全量の起点からレビューした内容まで変わっていないかを確かめる。
// 入力の誤り (解決できない版・レビューした内容に無いファイルや行) は error で返し、結果にしない。
func check(opts options) (result, error) {
	top, err := toplevel(opts.root)
	if err != nil {
		return result{}, err
	}
	g := gitRunner{root: top}

	base, err := g.commit(opts.base)
	if err != nil {
		return result{}, fmt.Errorf("-base をコミットに解決できません: %s", opts.base)
	}
	targetName := opts.rev
	if opts.worktree {
		targetName = "HEAD"
	}
	target, err := g.commit(targetName)
	if err != nil {
		return result{}, fmt.Errorf("レビューした内容のコミット (%s) を解決できません", targetName)
	}

	// 全量の起点がレビューした内容のコミットと同じなら、範囲 <起点>..<コミット> が空になり、
	// コミット済みのどの行も起点にあったままと報告される。ブランチの変更と前からある行を区別できない。
	if base == target {
		return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) と同じで、このブランチの変更と前からある行を区別できない", short(base), targetName)}, nil
	}
	ok, err := g.isAncestor(base, target)
	if err != nil {
		return result{}, err
	}
	if !ok {
		return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) の祖先ではない", short(base), targetName)}, nil
	}

	// 指摘の file は、レビューした内容にあるはず (根拠の照合 E1 を通っている)。無ければ入力の誤り。
	if opts.worktree {
		st, err := os.Stat(filepath.Join(top, filepath.FromSlash(opts.file)))
		if err != nil || !st.Mode().IsRegular() {
			return result{}, fmt.Errorf("作業ツリーに -file のファイルがありません: %s", opts.file)
		}
	} else if !g.exists(target, opts.file) {
		return result{}, fmt.Errorf("レビューした内容 (%s) に -file のファイルがありません: %s", opts.rev, opts.file)
	}

	if !g.exists(base, opts.file) {
		return result{kind: notHolds, reason: fmt.Sprintf("全量の起点 %s に同じパスのファイルが無い (このブランチで作った・改名した・移したファイル)", short(base))}, nil
	}
	if opts.worktree {
		if !g.exists(target, opts.file) {
			return result{kind: notHolds, reason: "HEAD に同じパスのファイルが無い (コミットしていないファイル)"}, nil
		}
	} else {
		// 結果のファイルで受け取ったレビューは、共有の作業ツリーでコミットしていない変更を見た可能性があり、
		// 結果のファイルからは分からない。ほかのファイルの変更は、指摘の file の行番号を変えないので見ない。
		changed, err := g.hasUncommittedChange(opts.file)
		if err != nil {
			return result{}, err
		}
		if changed {
			return result{kind: unverifiable, reason: "指摘のファイルにコミットしていない変更があり、レビューがそれを見たかが分からない"}, nil
		}
	}

	blamed, err := g.blame(base, target, opts)
	if err != nil {
		return result{}, err
	}
	return classify(base, opts.file, blamed), nil
}

// classify は blame の結果を行ごとに分類し、全体の結果を決める。
// 成り立たない行が 1 つでもあれば成り立たない、無くて確かめられない行があれば確かめられない。
func classify(base, file string, blamed []blameLine) result {
	res := result{kind: holds}
	for _, b := range blamed {
		l := lineResult{line: b.final}
		switch {
		case isZero(b.commit):
			l.kind, l.note = notHolds, "コミットしていない行"
		case !b.boundary:
			l.kind, l.note = notHolds, fmt.Sprintf("全量の起点より後のコミット %s が書いた・書き換えた行", short(b.commit))
		case b.commit != base:
			// 起点より前に分かれた履歴をマージすると、行がその分岐点まで遡り、そこが境界になる。
			// その行が起点にもあったかは、この結果からは決められない。
			l.kind, l.note = unverifiable, fmt.Sprintf("全量の起点を通らない履歴 (起点より前に分かれた履歴のマージなど) から来た行で、境界のコミットが %s。全量の起点にあったかを決められない", short(b.commit))
		case b.filename != file:
			l.kind, l.note = notHolds, fmt.Sprintf("このブランチで改名・移動したファイルの行 (全量の起点では %s)", b.filename)
		default:
			l.kind, l.note = holds, "全量の起点にあったまま"
		}
		res.lines = append(res.lines, l)
		switch {
		case l.kind == notHolds:
			res.kind = notHolds
		case l.kind == unverifiable && res.kind == holds:
			res.kind = unverifiable
		}
	}
	switch res.kind {
	case notHolds:
		res.reason = "対象の行のうち、全量の起点から変わった行がある"
	case unverifiable:
		res.reason = "対象の行のうち、全量の起点にあったかを決められない行がある"
	default:
		res.reason = fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))
	}
	return res
}

type blameLine struct {
	final    int    // レビューした内容での行番号
	commit   string // その行を最後に変えたコミット。範囲の外なら境界のコミット
	boundary bool   // 範囲 <起点>..<コミット> の境界のコミットか
	filename string // そのコミットでのパス
}

var blameHeader = regexp.MustCompile(`^([0-9a-f]{40}|[0-9a-f]{64}) [0-9]+ ([0-9]+)( [0-9]+)?$`)

// parsePorcelain は git blame --line-porcelain の出力を読む。
func parsePorcelain(out string) ([]blameLine, error) {
	var lines []blameLine
	var cur *blameLine
	for _, s := range strings.Split(out, "\n") {
		if cur == nil {
			if s == "" {
				continue
			}
			m := blameHeader.FindStringSubmatch(s)
			if m == nil {
				return nil, fmt.Errorf("git blame の出力を読めません: %q", s)
			}
			n, _ := strconv.Atoi(m[2])
			cur = &blameLine{final: n, commit: m[1]}
			continue
		}
		switch {
		case strings.HasPrefix(s, "\t"):
			if cur.filename == "" {
				return nil, fmt.Errorf("git blame の出力に行 %d のファイル名がありません", cur.final)
			}
			lines = append(lines, *cur)
			cur = nil
		case s == "boundary":
			cur.boundary = true
		case strings.HasPrefix(s, "filename "):
			name, err := unquotePath(strings.TrimPrefix(s, "filename "))
			if err != nil {
				return nil, err
			}
			cur.filename = name
		}
	}
	if cur != nil {
		return nil, fmt.Errorf("git blame の出力が行 %d の途中で終わっています", cur.final)
	}
	return lines, nil
}

// unquotePath は、git が引用符で囲んで出したパス (日本語や " を含むもの。例: "\346\227\245.md") を元に戻す。
func unquotePath(s string) (string, error) {
	if !strings.HasPrefix(s, `"`) {
		return s, nil
	}
	u, err := strconv.Unquote(s)
	if err != nil {
		return "", fmt.Errorf("git blame の出力のファイル名を読めません: %s", s)
	}
	return u, nil
}

func isZero(sha string) bool { return strings.Trim(sha, "0") == "" }

func short(sha string) string {
	if len(sha) > 12 {
		return sha[:12]
	}
	return sha
}

// gitRunner は、リポジトリのルートを基準に git を実行する。
type gitRunner struct{ root string }

func toplevel(dir string) (string, error) {
	out, _, err := gitRunner{root: dir}.run("rev-parse", "--show-toplevel")
	if err != nil {
		return "", fmt.Errorf("-root が git のリポジトリの中を指していません: %s", dir)
	}
	return strings.TrimSpace(out), nil
}

// run は git を実行し、標準出力と終了コードを返す。終了コードが 0 でなければ error も返す。
//
// どのディレクトリから実行しても同じ結果になるよう、-C でルートを指定する。パスを pathspec
// (パターンや先頭の : で始まる指定) として解釈させないよう GIT_LITERAL_PATHSPECS を立て、
// 読むだけの道具がインデックスを書き換えないよう GIT_OPTIONAL_LOCKS を 0 にする。
func (g gitRunner) run(args ...string) (string, int, error) {
	cmd := exec.Command("git", append([]string{"-C", g.root, "-c", "core.quotePath=false"}, args...)...)
	cmd.Env = append(os.Environ(), "GIT_LITERAL_PATHSPECS=1", "GIT_OPTIONAL_LOCKS=0")
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if err == nil {
		return stdout.String(), 0, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return stdout.String(), exitErr.ExitCode(), fmt.Errorf("git %s: %s", strings.Join(args, " "), strings.TrimSpace(stderr.String()))
	}
	return "", -1, fmt.Errorf("git を実行できません: %w", err)
}

// commit は版をコミットの完全な SHA に解決する。
func (g gitRunner) commit(rev string) (string, error) {
	out, _, err := g.run("rev-parse", "--verify", "--quiet", "--end-of-options", rev+"^{commit}")
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(out), nil
}

func (g gitRunner) isAncestor(a, b string) (bool, error) {
	_, code, err := g.run("merge-base", "--is-ancestor", a, b)
	switch code {
	case 0:
		return true, nil
	case 1:
		return false, nil
	default:
		return false, err
	}
}

// exists は、コミット commit に file のパスがあるかを返す。
func (g gitRunner) exists(commit, file string) bool {
	_, _, err := g.run("cat-file", "-e", commit+":"+file)
	return err == nil
}

// hasUncommittedChange は、file に HEAD からのコミットしていない変更 (ステージしたものを含む) があるかを返す。
func (g gitRunner) hasUncommittedChange(file string) (bool, error) {
	_, code, err := g.run("diff", "--quiet", "HEAD", "--", file)
	switch code {
	case 0:
		return false, nil
	case 1:
		return true, nil
	default:
		return false, err
	}
}

// blame は、範囲 <起点>..<コミット> で opts の行を最後に変えたコミットを求める。
// 範囲を起点で区切ると、起点から変わっていない行は起点が境界 (boundary) として報告される。
func (g gitRunner) blame(base, target string, opts options) ([]blameLine, error) {
	args := []string{
		"blame",
		// 範囲の中のルートのコミット (無関係な履歴のマージ) を境界として扱わず、そのコミットの行として報告させる
		"--root",
		// 設定 blame.ignoreRevsFile に挙げたコミットを無視すると、そのコミットが書き換えた行が起点のままと報告される
		"--ignore-revs-file", "",
		"--line-porcelain",
		"-L", fmt.Sprintf("%d,%d", opts.from, opts.to),
	}
	if opts.worktree {
		args = append(args, "--contents", filepath.Join(g.root, filepath.FromSlash(opts.file)))
	}
	args = append(args, base+".."+target, "--", opts.file)
	out, _, err := g.run(args...)
	if err != nil {
		return nil, err
	}
	lines, err := parsePorcelain(out)
	if err != nil {
		return nil, err
	}
	if want := opts.to - opts.from + 1; len(lines) != want {
		return nil, fmt.Errorf("git blame が %d 行を返しました (求めたのは %d 行)", len(lines), want)
	}
	return lines, nil
}

package main

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// TestMain は、利用者の git の設定 (グローバル・システム) がテストの結果を変えないように、
// HOME を一時ディレクトリに替え、システムの設定を読ませない。
func TestMain(m *testing.M) {
	home, err := os.MkdirTemp("", "lineorigin-home")
	if err != nil {
		panic(err)
	}
	for k, v := range map[string]string{
		"HOME":                home,
		"XDG_CONFIG_HOME":     home,
		"GIT_CONFIG_NOSYSTEM": "1",
		"GIT_AUTHOR_NAME":     "t",
		"GIT_AUTHOR_EMAIL":    "t@example.com",
		"GIT_COMMITTER_NAME":  "t",
		"GIT_COMMITTER_EMAIL": "t@example.com",
	} {
		os.Setenv(k, v)
	}
	code := m.Run()
	os.RemoveAll(home)
	os.Exit(code)
}

// repo は、テストごとに作る使い捨てのリポジトリ。
type repo struct {
	t   *testing.T
	dir string
}

func newRepo(t *testing.T) *repo {
	t.Helper()
	r := &repo{t: t, dir: t.TempDir()}
	r.git("init", "-q", "-b", "main")
	return r
}

func (r *repo) git(args ...string) string {
	r.t.Helper()
	cmd := exec.Command("git", append([]string{"-C", r.dir}, args...)...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		r.t.Fatalf("git %s: %v: %s", strings.Join(args, " "), err, stderr.String())
	}
	return strings.TrimSpace(stdout.String())
}

func (r *repo) write(path, content string) {
	r.t.Helper()
	p := filepath.Join(r.dir, path)
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		r.t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		r.t.Fatal(err)
	}
}

// commit はすべての変更をコミットし、そのコミットの SHA を返す。
func (r *repo) commit(msg string) string {
	r.t.Helper()
	r.git("add", "-A")
	r.git("commit", "-q", "--allow-empty", "-m", msg)
	return r.git("rev-parse", "HEAD")
}

type output struct {
	code   int
	kind   string
	reason string
	lines  map[string]string // "line 3" → 内訳
	stdout string
	stderr string
}

func runTool(t *testing.T, args ...string) output {
	t.Helper()
	var stdout, stderr bytes.Buffer
	o := output{code: run(args, &stdout, &stderr), lines: map[string]string{}, stdout: stdout.String(), stderr: stderr.String()}
	for _, l := range strings.Split(o.stdout, "\n") {
		k, v, _ := strings.Cut(l, ": ")
		switch {
		case k == "result":
			o.kind = v
		case k == "reason":
			o.reason = v
		case strings.HasPrefix(k, "line "):
			o.lines[k] = v
		}
	}
	return o
}

// check は、-root にリポジトリのルートを渡して道具を実行する。
func (r *repo) check(base string, extra ...string) output {
	r.t.Helper()
	return runTool(r.t, append([]string{"-root", r.dir, "-base", base}, extra...)...)
}

func wantKind(t *testing.T, o output, kind string) {
	t.Helper()
	if o.code != 0 {
		t.Fatalf("終了コードが %d (期待は 0)。stderr: %s", o.code, o.stderr)
	}
	if o.kind != kind {
		t.Fatalf("結果が %q (期待は %q)。出力:\n%s", o.kind, kind, o.stdout)
	}
}

func wantContains(t *testing.T, got, sub string) {
	t.Helper()
	if !strings.Contains(got, sub) {
		t.Fatalf("%q を含むはずが、%q だった", sub, got)
	}
}

// branched は、f.md を持つ起点のコミットを作り、そこから作業ブランチ br に切り替えた状態を返す。
func branched(t *testing.T) (*repo, string) {
	t.Helper()
	r := newRepo(t)
	r.write("f.md", "a\nb\nc\n")
	r.write("g.md", "g\n")
	base := r.commit("base")
	r.git("switch", "-q", "-c", "br")
	return r, base
}

func TestUnchangedLineHolds(t *testing.T) {
	r, base := branched(t)
	r.write("f.md", "a\nb\nC\n")
	r.commit("change line 3")

	o := r.check(base, "-file", "f.md", "-lines", "1", "-rev", "HEAD")
	wantKind(t, o, holds)
	wantContains(t, o.lines["line 1"], "全量の起点にあったまま")

	o = r.check(base, "-file", "f.md", "-lines", "3", "-rev", "HEAD")
	wantKind(t, o, notHolds)
	wantContains(t, o.lines["line 3"], "全量の起点より後のコミット")
}

func TestRangeWithOneChangedLineDoesNotHold(t *testing.T) {
	r, base := branched(t)
	r.write("f.md", "a\nb\nC\n")
	r.commit("change line 3")

	o := r.check(base, "-file", "f.md", "-lines", "1-3", "-rev", "HEAD")
	wantKind(t, o, notHolds)
	if len(o.lines) != 3 {
		t.Fatalf("行ごとの内訳が %d 行 (期待は 3 行)。出力:\n%s", len(o.lines), o.stdout)
	}
}

// 上に行を足して行番号がずれても、行そのものが変わっていなければ成り立つ。
func TestLineShiftedByInsertionHolds(t *testing.T) {
	r, base := branched(t)
	r.write("f.md", "new\na\nb\nc\n")
	r.commit("insert above")

	wantKind(t, r.check(base, "-file", "f.md", "-lines", "2", "-rev", "HEAD"), holds)
	wantKind(t, r.check(base, "-file", "f.md", "-lines", "1", "-rev", "HEAD"), notHolds)
}

func TestFileCreatedInBranchDoesNotHold(t *testing.T) {
	r, base := branched(t)
	r.write("n.md", "n\n")
	r.commit("new file")

	o := r.check(base, "-file", "n.md", "-lines", "1", "-rev", "HEAD")
	wantKind(t, o, notHolds)
	wantContains(t, o.reason, "同じパスのファイルが無い")
}

// このブランチで改名したファイルの行は、git blame が改名を追って起点まで遡るが、成り立たない。
func TestFileRenamedInBranchDoesNotHold(t *testing.T) {
	r, base := branched(t)
	r.git("mv", "g.md", "h.md")
	r.commit("rename")

	wantKind(t, r.check(base, "-file", "h.md", "-lines", "1", "-rev", "HEAD"), notHolds)
}

// 起点に同じパスのファイルがあっても、それを消した後に別のファイルをそのパスへ改名したなら、
// 行は改名前のファイルから来ているので成り立たない。
func TestFileRenamedOntoDeletedPathDoesNotHold(t *testing.T) {
	r, base := branched(t)
	r.git("rm", "-q", "g.md")
	r.commit("delete g.md")
	r.git("mv", "f.md", "g.md")
	r.commit("rename f.md to g.md")

	o := r.check(base, "-file", "g.md", "-lines", "1", "-rev", "HEAD")
	wantKind(t, o, notHolds)
	wantContains(t, o.lines["line 1"], "全量の起点では f.md")
}

// 起点より前に改名したファイルは、起点で同じパスにあるので成り立つ。
func TestFileRenamedBeforeBaseHolds(t *testing.T) {
	r := newRepo(t)
	r.write("old/f.md", "a\nb\n")
	r.commit("c0")
	r.git("mv", "old/f.md", "f.md")
	base := r.commit("rename before base")
	r.git("switch", "-q", "-c", "br")
	r.write("other.md", "x\n")
	r.commit("branch")

	wantKind(t, r.check(base, "-file", "f.md", "-lines", "1-2", "-rev", "HEAD"), holds)
}

func TestUncommittedChangeInFileIsUnverifiableWithRev(t *testing.T) {
	r, base := branched(t)
	r.write("g.md", "branch\n")
	r.commit("branch")

	r.write("f.md", "a\nb\nc\nd\n")
	o := r.check(base, "-file", "f.md", "-lines", "1", "-rev", "HEAD")
	wantKind(t, o, unverifiable)
	wantContains(t, o.reason, "コミットしていない変更")

	// ステージした変更も同じ
	r.git("add", "f.md")
	wantKind(t, r.check(base, "-file", "f.md", "-lines", "1", "-rev", "HEAD"), unverifiable)
