func (g gitRunner) blob(commit, file string) (string, error) {
	out, code, err := g.run("rev-parse", "--verify", "--quiet", commit+":"+file)
	switch {
	case err == nil:
		return strings.TrimSpace(out), nil
	case code == 1:
		return "", nil
	default:
		return "", err
	}
