		"--no-textconv",
		"--line-porcelain",
		"-L", fmt.Sprintf("%d,%d", opts.from, opts.to),
	}
	if opts.worktree {
		args = append(args, "--contents", filepath.Join(g.root, filepath.FromSlash(opts.file)))
	}
	args = append(args, base+".."+target, "--", opts.file)
